//! Neighborhoods: move generators that push `(move, delta)` pairs into a
//! [`Visitor`]. Nothing is materialised.

use crate::{DefaultRng, Evaluated, Model, Move, State};
use rand::{Rng, SeedableRng};
use std::marker::PhantomData;
use std::ops::ControlFlow;

/// Receives the moves generated by a [`Neighborhood`].
pub trait Visitor<M, C> {
    /// Offer a move and its delta. `Break` asks the neighborhood to stop.
    fn visit(&mut self, m: M, delta: C) -> ControlFlow<()>;

    /// Moves whose delta is `>=` this value cannot be selected anymore.
    /// Neighborhoods *may* use it to skip work; ignoring it is always correct.
    #[inline]
    fn bound(&self) -> Option<C> {
        None
    }

    /// True when no move whose delta is `>= lower` can be selected anymore,
    /// so a neighborhood that knows a lower bound on the deltas of a group of
    /// moves may skip the whole group. Unlike [`bound`](Self::bound), this
    /// also works for visitors that may still take a move *equal* to the
    /// best so far (random tie-breaking): they skip only `lower > best`.
    #[inline]
    fn can_skip(&self, lower: C) -> bool
    where
        C: PartialOrd,
    {
        self.bound().is_some_and(|b| lower >= b)
    }
}

impl<M, C, F: FnMut(M, C) -> ControlFlow<()>> Visitor<M, C> for F {
    #[inline]
    fn visit(&mut self, m: M, delta: C) -> ControlFlow<()> {
        self(m, delta)
    }
}

/// A move generator. Typical implementation: nested loops, `?` to stop early,
/// and `s.delta_of(&m)` for the delta.
///
/// ```ignore
/// fn explore<V: Visitor<Swap, C>>(&mut self, s: &Evaluated<P>, v: &mut V) -> ControlFlow<()> {
///     for i in 0..s.size() { for j in i + 1..s.size() {
///         let m = Swap { i, j };
///         v.visit(m, s.delta_of(&m))?;
///     }}
///     ControlFlow::Continue(())
/// }
/// ```
pub trait Neighborhood<S: Model> {
    type Move: Move<S>;
    fn explore<V: Visitor<Self::Move, S::Cost>>(
        &mut self,
        s: &Evaluated<S>,
        v: &mut V,
    ) -> ControlFlow<()>;
    /// Called when a run starts: build candidate lists, size buffers, seed an
    /// internal RNG from the run's RNG…
    #[inline]
    fn start<R: Rng + ?Sized>(&mut self, _s: &Evaluated<S>, _rng: &mut R) {}
}

/// Moves only, no deltas: the simple way to describe a neighborhood when the
/// deltas come from `delta_of` anyway. Turn one into a [`Neighborhood`] with
/// [`WithDeltas`] (deltas from `delta_of`) or [`FullEvaluation`]
/// (apply/evaluate/undo). [`moves_fn`] closures are neighborhoods directly.
pub trait MoveSource<S: Model> {
    type Move: Move<S>;
    type Iter<'a>: Iterator<Item = Self::Move>
    where
        Self: 'a,
        S: 'a;
    fn moves<'a>(&'a mut self, s: &'a S) -> Self::Iter<'a>;
}

#[inline]
fn explore_source<S: Model, MS: MoveSource<S>, V: Visitor<MS::Move, S::Cost>>(
    ms: &mut MS,
    s: &Evaluated<S>,
    v: &mut V,
) -> ControlFlow<()> {
    for m in ms.moves(s) {
        let d = s.delta_of(&m);
        v.visit(m, d)?;
    }
    ControlFlow::Continue(())
}

/// A [`MoveSource`] as a [`Neighborhood`]: each move's delta is `delta_of(&m)`.
pub struct WithDeltas<MS>(pub MS);

impl<S: Model, MS: MoveSource<S>> Neighborhood<S> for WithDeltas<MS> {
    type Move = MS::Move;
    #[inline]
    fn explore<V: Visitor<MS::Move, S::Cost>>(
        &mut self,
        s: &Evaluated<S>,
        v: &mut V,
    ) -> ControlFlow<()> {
        explore_source(&mut self.0, s, v)
    }
}

/// A closure returning an iterator of moves: both a [`MoveSource`] and a
/// [`Neighborhood`] (deltas from `delta_of`).
pub struct MovesFn<F, I> {
    f: F,
    _iter: PhantomData<fn() -> I>,
}

/// `moves_fn(|s: &Tour| (0..s.len()).flat_map(...))`
pub fn moves_fn<S, I, F>(f: F) -> MovesFn<F, I>
where
    S: Model,
    F: FnMut(&S) -> I,
    I: Iterator,
    I::Item: Move<S>,
{
    MovesFn {
        f,
        _iter: PhantomData,
    }
}

impl<S, I, F> MoveSource<S> for MovesFn<F, I>
where
    S: Model,
    F: FnMut(&S) -> I,
    I: Iterator,
    I::Item: Move<S>,
{
    type Move = I::Item;
    type Iter<'a>
        = I
    where
        Self: 'a,
        S: 'a;
    #[inline]
    fn moves<'a>(&'a mut self, s: &'a S) -> I {
        (self.f)(s)
    }
}

impl<S, I, F> Neighborhood<S> for MovesFn<F, I>
where
    S: Model,
    F: FnMut(&S) -> I,
    I: Iterator,
    I::Item: Move<S>,
{
    type Move = I::Item;
    #[inline]
    fn explore<V: Visitor<I::Item, S::Cost>>(
        &mut self,
        s: &Evaluated<S>,
        v: &mut V,
    ) -> ControlFlow<()> {
        explore_source(self, s, v)
    }
}

/// Neighborhood for models without delta formulas: apply → `evaluate()` →
/// apply the inverse, on a scratch copy synchronised once per iteration.
/// One full evaluation per move and no clone. Moves with a delta formula use
/// it; moves without an inverse fall back to `delta_of` (clone + evaluate).
pub struct FullEvaluation<MS, S> {
    pub source: MS,
    scratch: Option<S>,
}

impl<MS, S> FullEvaluation<MS, S> {
    pub fn new(source: MS) -> Self {
        FullEvaluation {
            source,
            scratch: None,
        }
    }
}

impl<S: Model, MS: MoveSource<S>> Neighborhood<S> for FullEvaluation<MS, S> {
    type Move = MS::Move;
    fn explore<V: Visitor<MS::Move, S::Cost>>(
        &mut self,
        s: &Evaluated<S>,
        v: &mut V,
    ) -> ControlFlow<()> {
        let scratch = match &mut self.scratch {
            Some(t) => {
                t.clone_from(s);
                t
            }
            None => self.scratch.insert((**s).clone()),
        };
        for m in self.source.moves(s) {
            let d = if let Some(d) = m.delta(s) {
                d
            } else if let Some(inv) = m.inverse(scratch) {
                m.apply(scratch);
                let after = scratch.evaluate();
                inv.apply(scratch);
                after - s.cost()
            } else {
                s.delta_of(&m)
            };
            v.visit(m, d)?;
        }
        ControlFlow::Continue(())
    }
}

/// Draws one random move, ideally in O(1), for neighborhoods too large to scan.
pub trait Sampler<S: Model> {
    type Move: Move<S>;
    fn sample<R: Rng + ?Sized>(&mut self, s: &Evaluated<S>, rng: &mut R) -> Option<Self::Move>;
}

/// `k` random moves of a [`Sampler`] per iteration, as a [`Neighborhood`]
/// (METSlib's `swap_neighborhood(rng, k)`). Its RNG is seeded from the run's
/// RNG in `start`, so it is covered by the run's seed.
pub struct Sampled<N> {
    pub sampler: N,
    pub k: usize,
    rng: DefaultRng,
}

impl<N> Sampled<N> {
    pub fn new(sampler: N, k: usize) -> Self {
        Sampled {
            sampler,
            k,
            rng: DefaultRng::seed_from_u64(0),
        }
    }
}

impl<S: Model, N: Sampler<S>> Neighborhood<S> for Sampled<N> {
    type Move = N::Move;
    fn explore<V: Visitor<N::Move, S::Cost>>(
        &mut self,
        s: &Evaluated<S>,
        v: &mut V,
    ) -> ControlFlow<()> {
        for _ in 0..self.k {
            if let Some(m) = self.sampler.sample(s, &mut self.rng) {
                let d = s.delta_of(&m);
                v.visit(m, d)?;
            }
        }
        ControlFlow::Continue(())
    }
    fn start<R: Rng + ?Sized>(&mut self, _s: &Evaluated<S>, rng: &mut R) {
        self.rng = DefaultRng::seed_from_u64(rng.next_u64());
    }
}

/// Keeps the best move whose delta is below a bound. The building block of
/// descent methods; reusable in your own algorithms.
pub struct BestMove<M, C> {
    pub best: Option<(M, C)>,
    pub bound: C,
    /// Stop at the first acceptable move (first improvement).
    pub first: bool,
}

impl<M, C: crate::Cost> BestMove<M, C> {
    /// Accept only moves with `delta < bound`.
    pub fn below(bound: C) -> Self {
        BestMove {
            best: None,
            bound,
            first: false,
        }
    }
    /// Accept only improving moves, using the state's tolerance.
    pub fn improving<S: Model<Cost = C>, R>(st: &State<S, R>) -> Self {
        Self::below(-st.tolerance())
    }
    /// Stop at the first acceptable move.
    pub fn first(mut self) -> Self {
        self.first = true;
        self
    }
}

impl<M, C: crate::Cost> Visitor<M, C> for BestMove<M, C> {
    #[inline]
    fn visit(&mut self, m: M, delta: C) -> ControlFlow<()> {
        if delta < self.bound {
            self.bound = delta;
            self.best = Some((m, delta));
            if self.first {
                return ControlFlow::Break(());
            }
        }
        ControlFlow::Continue(())
    }
    #[inline]
    fn bound(&self) -> Option<C> {
        Some(self.bound)
    }
}

/// All moves of a neighborhood with their deltas (debugging and tests).
pub fn collect_moves<S: Model, N: Neighborhood<S>>(
    n: &mut N,
    s: &Evaluated<S>,
) -> Vec<(N::Move, S::Cost)> {
    let mut out = Vec::new();
    let _ = n.explore(s, &mut |m, d| {
        out.push((m, d));
        ControlFlow::Continue(())
    });
    out
}
